def load_existing(slug):
    """读取现有 JSON 文件中的 questions 数组"""
    filepath = os.path.join(DATA_DIR, f"{slug}.json")
    if os.path.exists(filepath):
        with open(filepath, 'r', encoding='utf-8') as f:
            data = json.load(f)
        return data.get("questions", [])
    return []

def main():
    for ch in CHAPTERS:
        slug = ch["slug"]
        existing = load_existing(slug)
        merged = existing + ch["new_questions"]

        output = {
            "seo_metadata": ch["seo"],
            "questions": merged
        }

        filepath = os.path.join(DATA_DIR, f"{slug}.json")
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(output, f, indent=2, ensure_ascii=False)

        print(f"✅ {slug}.json: {len(existing)} existing + {len(ch['new_questions'])} new = {len(merged)} total")

    print(f"\n🎉 All {len(CHAPTERS)} chapters written to {DATA_DIR}/")

if __name__ == "__main__":
    main()
